import React from "react";
import { Box, Typography } from "@mui/material";
import Grid from "./Grid";
import { ZB_COLORS } from "../theme";

const values = [
  { icon: "🎯", title: "Purpose-driven", desc: "Everything we build is designed to create real impact for Zambian professionals." },
  { icon: "🤝", title: "Community-first", desc: "We grow together. ZBRIDGE is built by and for the African professional community." },
  { icon: "🔬", title: "Learn by doing", desc: "Simulations, not textbooks. Real scenarios that prepare you for real challenges." },
  { icon: "🌍", title: "African context", desc: "Our content is built around the realities and opportunities of the African economy." },
];

export default function AboutSection() {
  return (
    <Box sx={{ maxWidth: 900, mx: "auto", px: { xs: 2, md: 4 }, py: { xs: 4, md: 6 } }}>
      <Typography sx={{ fontSize: "0.72rem", textTransform: "uppercase", letterSpacing: "0.1em", color: ZB_COLORS.gold, fontWeight: 600, mb: 1, fontFamily: "DM Sans" }}>Our story</Typography>
      <Typography variant="h4" sx={{ color: "#fff", mb: 0.5 }}>About ZBRIDGE</Typography>
      <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 4, fontSize: "1rem", lineHeight: 1.75, maxWidth: 700 }}>
        ZBRIDGE is a career-readiness platform that transforms education into action. Through industry-inspired
        simulations and guided reflections, we help students and young professionals build real skills, explore
        career paths, and stand out in a competitive world — all before their first job.
      </Typography>
      <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 5, fontSize: "1rem", lineHeight: 1.75, maxWidth: 700 }}>
        Whether you're preparing for your future or sharpening your edge, ZBRIDGE bridges the gap between what you
        know and what the world expects. Learn by doing. Grow with confidence. Enter the world ready.
      </Typography>

      <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", fontSize: "1.25rem", mb: 3 }}>Our values</Typography>
      <Grid container spacing={2}>
        {values.map(v => (
          <Grid item xs={12} sm={6} key={v.title}>
            <Box sx={{ background: ZB_COLORS.cardBg, border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "12px", p: 3, display: "flex", gap: 2 }}>
              <Box sx={{ fontSize: "1.5rem", flexShrink: 0 }}>{v.icon}</Box>
              <Box>
                <Typography sx={{ fontFamily: "Sora", fontWeight: 600, color: "#fff", mb: 0.5 }}>{v.title}</Typography>
                <Typography sx={{ fontSize: "0.875rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", lineHeight: 1.6 }}>{v.desc}</Typography>
              </Box>
            </Box>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
}
